18	// statusStyles holds pre-built lipgloss styles and terminal metadata.
19	type statusStyles struct {
20		colorEnabled bool
21		width        int
22	
23		// Styles
24		green  lipgloss.Style
25		red    lipgloss.Style
26		gray   lipgloss.Style
27		bold   lipgloss.Style
28		dim    lipgloss.Style
29		agent  lipgloss.Style // amber/orange for agent names
30		cyan   lipgloss.Style
31		yellow lipgloss.Style // yellow for stale warnings
32	}
33	
34	// newStatusStyles creates styles appropriate for the output writer.
35	func newStatusStyles(w io.Writer) statusStyles {
36		useColor := shouldUseColor(w)
37		width := getTerminalWidth(w)
38	
39		s := statusStyles{
40			colorEnabled: useColor,
41			width:        width,
42		}
43	
44		if useColor {
45			s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
46			s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
47			s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
48			s.bold = lipgloss.NewStyle().Bold(true)
49			s.dim = lipgloss.NewStyle().Faint(true)
50			s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
51			s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
52			s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
53		}
54	
55		return s
56	}
57	
58	// render applies a style to text only when color is enabled.
59	func (s statusStyles) render(style lipgloss.Style, text string) string {
60		if !s.colorEnabled {
61			return text
62		}
63		return style.Render(text)
64	}
65	
66	// shouldUseColor returns true if the writer supports color output.
67	func shouldUseColor(w io.Writer) bool {
68		return interactive.ShouldStyle(w)
69	}
