94	// formatTokenCount formats a token count for display.
95	// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
96	func formatTokenCount(n int) string {
97		if n < 1000 {
98			return strconv.Itoa(n)
99		}
100		f := float64(n) / 1000.0
101		s := fmt.Sprintf("%.1f", f)
102		// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
103		s = strings.TrimSuffix(s, ".0")
104		return s + "k"
105	}
106	
107	// totalTokens recursively sums all token fields including subagent tokens.
108	func totalTokens(tu *agent.TokenUsage) int {
109		if tu == nil {
110			return 0
111		}
112		total := saturatingIntAdd(tu.InputTokens, tu.CacheCreationTokens)
113		total = saturatingIntAdd(total, tu.CacheReadTokens)
114		total = saturatingIntAdd(total, tu.OutputTokens)
115		total = saturatingIntAdd(total, totalTokens(tu.SubagentTokens))
116		return total
117	}
