119	// explainRow is one entry in a metadata block: dim label + plain value.
120	type explainRow struct {
121		Label string
122		Value string
123	}
124	
125	// identityBullet renders "● <label> <id>\n". Bullet is brand orange when color
126	// is enabled; ID is also orange to mirror the existing checkpoint header. When
127	// id is empty (e.g., temporary checkpoints append "[temporary]" to the label
128	// instead of using an id slot), the trailing space + id is suppressed.
129	func (s statusStyles) identityBullet(label, id string) string {
130		if id == "" {
131			if !s.colorEnabled {
132				return fmt.Sprintf("● %s\n", label)
133			}
134			bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
135			return fmt.Sprintf("%s %s\n", bullet, s.render(s.bold, label))
136		}
137		if !s.colorEnabled {
138			return fmt.Sprintf("● %s %s\n", label, id)
139		}
140		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
141		idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), id)
142		return fmt.Sprintf("%s %s %s\n", bullet, s.render(s.bold, label), idStyled)
143	}
144	
145	// listIdentityBullet renders "● <id>  <suffix>\n" — orange bullet, bold-orange ID,
146	// then plain (or dimmed) suffix. Used by the explain list view where the ID is
147	// the primary identifier (different ordering from identityBullet, which puts
148	// the static label first).
149	func (s statusStyles) listIdentityBullet(id, suffix string) string {
150		if !s.colorEnabled {
151			if suffix == "" {
152				return fmt.Sprintf("● %s\n", id)
153			}
154			return fmt.Sprintf("● %s  %s\n", id, suffix)
155		}
156		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
157		idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")).Bold(true), id)
158		if suffix == "" {
159			return fmt.Sprintf("%s %s\n", bullet, idStyled)
160		}
161		return fmt.Sprintf("%s %s  %s\n", bullet, idStyled, suffix)
162	}
163	
164	// successBullet renders "✓ <label>\n" — green checkmark + bold label.
165	func (s statusStyles) successBullet(label string) string {
166		if !s.colorEnabled {
167			return fmt.Sprintf("✓ %s\n", label)
168		}
169		return fmt.Sprintf("%s %s\n", s.render(s.green, "✓"), s.render(s.bold, label))
170	}
171	
172	// failureBullet renders "✗ <label>\n" — red ✗ + bold label.
173	func (s statusStyles) failureBullet(label string) string {
174		if !s.colorEnabled {
175			return fmt.Sprintf("✗ %s\n", label)
176		}
177		return fmt.Sprintf("%s %s\n", s.render(s.red, "✗"), s.render(s.bold, label))
178	}
179	
180	// renderIdentity returns identityBullet + metadataRows + horizontalRule + trailing newline.
181	// This is the exact shape used by formatCheckpointHeader; rendering an entire
182	// header block is one call instead of three.
183	func (s statusStyles) renderIdentity(label, id string, rows []explainRow) string {
184		var b strings.Builder
185		b.WriteString(s.identityBullet(label, id))
186		b.WriteString(s.metadataRows(rows))
187		b.WriteString(s.horizontalRule(s.width))
188		b.WriteString("\n")
189		return b.String()
190	}
191	
192	// renderSuccess returns successBullet + metadataRows. No trailing rule (success
193	// blocks are short and don't precede a body section).
194	func (s statusStyles) renderSuccess(label string, rows []explainRow) string {
195		if len(rows) == 0 {
196			return s.successBullet(label)
197		}
198		return s.successBullet(label) + s.metadataRows(rows)
199	}
200	
201	// renderFailure returns failureBullet + metadataRows. Used when a command
202	// prints a styled error block to errW before returning *SilentError.
203	func (s statusStyles) renderFailure(label string, rows []explainRow) string {
204		if len(rows) == 0 {
205			return s.failureBullet(label)
206		}
207		return s.failureBullet(label) + s.metadataRows(rows)
208	}
209	
210	// metadataRow renders a single key/value row using a 7-char min-padded label.
211	// 7-char-pad + 2-space-gutter is visually equivalent to the existing
212	// formatCheckpointHeader's %-9s + no-gutter (see explain.go) for any label up
213	// to 9 chars, and the explicit gutter scales cleanly when a longer label
214	// (e.g. "checkpoints", 11 chars) is present.
215	//
216	// Use metadataRows for multi-row blocks where alignment depends on the
217	// widest label.
218	func (s statusStyles) metadataRow(label, value string) string {
219		width := 7
220		if l := len(label); l > width {
221			width = l
222		}
223		return s.metadataRowsWithWidth([]explainRow{{Label: label, Value: value}}, width)
224	}
225	
226	// metadataRows joins rows with consistent label-column width:
227	// max(7, widest label in slice). See metadataRow for the 7 vs 9
228	// equivalence note.
229	func (s statusStyles) metadataRows(rows []explainRow) string {
230		width := 7
231		for _, r := range rows {
232			if l := len(r.Label); l > width {
233				width = l
234			}
235		}
236		return s.metadataRowsWithWidth(rows, width)
237	}
238	
239	// metadataRowsWithWidth is the underlying renderer used by metadataRow and
240	// metadataRows. The caller computes the column width; this function owns the
241	// byte layout (2-space indent, padded label, 2-space gutter, value, newline)
242	// and the empty-label continuation branch (4-space hanging indent, no dim
243	// styling — used for multi-line items beneath a parent label like "causes").
244	//
245	// The min=7 default chosen by metadataRow/metadataRows produces output
246	// identical to formatCheckpointHeader's %-9s + no-gutter rendering at
247	// explain.go for any label up to 9 chars.
248	func (s statusStyles) metadataRowsWithWidth(rows []explainRow, width int) string {
249		var b strings.Builder
250		for _, r := range rows {
251			// Empty-label rows are continuation lines (e.g., bullet items under a "causes" row).
252			// They render with a 4-space hanging indent and no dim styling.
253			if r.Label == "" {
254				fmt.Fprintf(&b, "    %s\n", r.Value)
255				continue
256			}
257			paddedLabel := fmt.Sprintf("%-*s", width, r.Label)
258			if s.colorEnabled {
259				paddedLabel = s.render(s.dim, paddedLabel)
260			}
261			// Two-space indent + padded label + two-space gutter + value + newline.
262			fmt.Fprintf(&b, "  %s  %s\n", paddedLabel, r.Value)
263		}
264		return b.String()
265	}
266	
267	// horizontalRule renders a dimmed horizontal rule of the given width.
268	func (s statusStyles) horizontalRule(width int) string {
269		rule := strings.Repeat("─", width)
270		return s.render(s.dim, rule)
271	}
272	
273	// sectionRule renders a section header like: ── Active Sessions ────────────
274	func (s statusStyles) sectionRule(label string, width int) string {
275		prefix := "── "
276		content := label + " "
277		usedWidth := len([]rune(prefix)) + len([]rune(content))
278		trailing := width - usedWidth
279		if trailing < 1 {
280			trailing = 1
281		}
282	
283		var b strings.Builder
284		b.WriteString(s.render(s.dim, "── "))
285		b.WriteString(s.render(s.dim, label))
286		b.WriteString(" ")
287		b.WriteString(s.render(s.dim, strings.Repeat("─", trailing)))
288		return b.String()
289	}
290	
291	// activeTimeDisplay formats a last interaction time for display.
292	// Returns "active now" for recent activity (<1min), otherwise "active Xm ago".
293	func activeTimeDisplay(lastInteraction *time.Time) string {
294		if lastInteraction == nil {
295			return ""
296		}
297		d := time.Since(*lastInteraction)
298		if d < time.Minute {
299			return "active now"
300		}
301		return "active " + timeAgo(*lastInteraction)
302	}
